import { db } from "@tepian-k3/db/client";
import { userTrainingProfiles, documents } from "@tepian-k3/db/schema";
import { eq, and, isNull, sql } from "@tepian-k3/db";
import { Effect } from "effect";
import { logError } from "@tepian-k3/services/logger";
import { TRPCError } from "@tepian-k3/utils/error";

const profileQueries = {
  getProfileByUserId(userId: string) {
    return Effect.tryPromise({
      try: async () => {
        const profile = await db.query.userTrainingProfiles.findFirst({
          where: and(
            eq(userTrainingProfiles.userId, userId),
            isNull(userTrainingProfiles.deletedAt),
          ),
        });
        return profile ?? null;
      },
      catch: (error) => {
        logError(
          "profileQueries.getProfileByUserId",
          "Failed to fetch training profile",
          {
            userId,
            error,
          },
        );
        throw new TRPCError({
          code: "INTERNAL_SERVER_ERROR",
          message: "Gagal mengambil data profil pelatihan.",
          cause: error,
        });
      },
    });
  },

  upsertProfile(userId: string, data: any) {
    return Effect.tryPromise({
      try: async () => {
        const [updatedProfile] = await db
          .insert(userTrainingProfiles)
          .values({
            ...data,
            userId,
          })
          .onConflictDoUpdate({
            target: userTrainingProfiles.userId,
            set: {
              ...data,
              updatedAt: new Date().toISOString(),
            },
          })
          .returning();

        if (!updatedProfile) {
          throw new TRPCError({
            code: "INTERNAL_SERVER_ERROR",
            message: "Gagal memperbarui profil pelatihan.",
          });
        }
        return updatedProfile;
      },
      catch: (error) => {
        logError(
          "profileQueries.upsertProfile",
          "Failed to upsert training profile",
          {
            userId,
            data,
            error,
          },
        );
        if (error instanceof TRPCError) throw error;
        throw new TRPCError({
          code: "INTERNAL_SERVER_ERROR",
          message: "Gagal memperbarui profil pelatihan.",
          cause: error,
        });
      },
    });
  },

  getDocumentsByUserId(userId: string) {
    return Effect.tryPromise({
      try: () =>
        db.query.documents.findMany({
          where: and(
            eq(documents.entityType, "user"),
            eq(documents.entityId, userId),
            isNull(documents.deletedAt),
          ),
        }),
      catch: (error) => {
        logError(
          "profileQueries.getDocumentsByUserId",
          "Failed to fetch user documents",
          {
            userId,
            error,
          },
        );
        throw new TRPCError({
          code: "INTERNAL_SERVER_ERROR",
          message: "Gagal mengambil dokumen pendukung.",
          cause: error,
        });
      },
    });
  },

  createDocument(
    userId: string,
    docData: {
      documentNumber: string;
      type: any;
      title: string;
      fileUrl: string;
      fileName: string;
      fileSize?: number;
      mimeType?: string;
    },
  ) {
    return Effect.tryPromise({
      try: async () => {
        return await db.transaction(async (tx) => {
          // Soft-delete existing active document of the same type for this user
          await tx
            .update(documents)
            .set({ deletedAt: sql`CURRENT_TIMESTAMP` })
            .where(
              and(
                eq(documents.entityType, "user"),
                eq(documents.entityId, userId),
                eq(documents.type, docData.type),
                isNull(documents.deletedAt),
              ),
            );

          const [doc] = await tx
            .insert(documents)
            .values({
              ...docData,
              entityType: "user",
              entityId: userId,
              uploadedByUserId: userId,
              status: "draft",
            })
            .returning();

          if (!doc) {
            throw new TRPCError({
              code: "INTERNAL_SERVER_ERROR",
              message: "Gagal menyimpan dokumen pendukung.",
            });
          }
          return doc;
        });
      },
      catch: (error) => {
        logError(
          "profileQueries.createDocument",
          "Failed to create user document",
          {
            userId,
            docData,
            error,
          },
        );
        if (error instanceof TRPCError) throw error;
        throw new TRPCError({
          code: "INTERNAL_SERVER_ERROR",
          message: "Gagal menyimpan dokumen pendukung.",
          cause: error,
        });
      },
    });
  },

  deleteDocument(documentId: string, userId: string) {
    return Effect.tryPromise({
      try: async () => {
        const [deletedDoc] = await db
          .update(documents)
          .set({
            deletedAt: sql`CURRENT_TIMESTAMP`,
          })
          .where(
            and(
              eq(documents.id, documentId),
              eq(documents.entityId, userId),
              eq(documents.entityType, "user"),
              isNull(documents.deletedAt),
            ),
          )
          .returning();

        if (!deletedDoc) {
          throw new TRPCError({
            code: "NOT_FOUND",
            message: "Dokumen tidak ditemukan atau sudah dihapus.",
          });
        }
        return deletedDoc;
      },
      catch: (error) => {
        logError(
          "profileQueries.deleteDocument",
          "Failed to delete user document",
          {
            documentId,
            userId,
            error,
          },
        );
        if (error instanceof TRPCError) throw error;
        throw new TRPCError({
          code: "INTERNAL_SERVER_ERROR",
          message: "Gagal menghapus dokumen pendukung.",
          cause: error,
        });
      },
    });
  },

  upsertTrainingProfileAndDocuments(userId: string, input: any) {
    return Effect.tryPromise({
      try: () =>
        db.transaction(async (tx) => {
          const profileData: any = {};
          const profileKeys = [
            "participantName",
            "participantNik",
            "participantBirthPlace",
            "participantBirthDate",
            "participantPhone",
            "participantAddress",
            "participantBloodType",
            "companyName",
            "companyAddress",
            "companyProvinceId",
            "companyRegencyId",
            "companyDistrictId",
            "companyKbli",
          ];

          for (const key of profileKeys) {
            if (input[key] !== undefined) {
              profileData[key] = input[key];
            }
          }

          if (Object.keys(profileData).length > 0) {
            await tx
              .insert(userTrainingProfiles)
              .values({
                ...profileData,
                userId,
              })
              .onConflictDoUpdate({
                target: userTrainingProfiles.userId,
                set: {
                  ...profileData,
                  updatedAt: new Date().toISOString(),
                },
              });
          }

          const docsToInsert = [
            {
              urlKey: "ktpDocUrl",
              nameKey: "ktpDocName",
              type: "id_card",
              title: "Scan Kartu Identitas (KTP)",
            },
            {
              urlKey: "employmentLetterUrl",
              nameKey: "employmentLetterName",
              type: "employment_letter",
              title: "Surat Keterangan Kerja",
            },
            {
              urlKey: "consentLetterUrl",
              nameKey: "consentLetterName",
              type: "employment_contract",
              title: "Surat Pernyataan Kesediaan",
            },
            {
              urlKey: "diplomaUrl",
              nameKey: "diplomaName",
              type: "diploma",
              title: "Ijazah Terakhir",
            },
            {
              urlKey: "passPhotoUrl",
              nameKey: "passPhotoName",
              type: "pass_photo",
              title: "Pass Foto Latar Merah",
            },
          ];

          for (const doc of docsToInsert) {
            const fileUrl = input[doc.urlKey];
            const fileName = input[doc.nameKey] || `${doc.title}`;
            if (fileUrl) {
              const existingDoc = await tx.query.documents.findFirst({
                where: and(
                  eq(documents.entityType, "user"),
                  eq(documents.entityId, userId),
                  eq(documents.type, doc.type as any),
                  isNull(documents.deletedAt),
                ),
              });

              if (existingDoc) {
                await tx
                  .update(documents)
                  .set({
                    fileUrl,
                    fileName,
                    updatedAt: new Date().toISOString(),
                  })
                  .where(eq(documents.id, existingDoc.id));
              } else {
                const dateStr = new Date()
                  .toISOString()
                  .slice(0, 10)
                  .replace(/-/g, "");
                const docNo = `DOC-${dateStr}-${Math.floor(1000 + Math.random() * 9000)}`;
                await tx.insert(documents).values({
                  documentNumber: docNo,
                  type: doc.type as any,
                  title: doc.title,
                  fileUrl,
                  fileName,
                  entityType: "user",
                  entityId: userId,
                  uploadedByUserId: userId,
                  status: "draft",
                });
              }
            }
          }
          return { success: true };
        }),
      catch: (error) => {
        logError(
          "profileQueries.upsertTrainingProfileAndDocuments",
          "Failed to upsert training profile and documents",
          { error, userId },
        );
        if (error instanceof TRPCError) throw error;
        throw new TRPCError({
          code: "INTERNAL_SERVER_ERROR",
          message: "Gagal menyimpan data.",
        });
      },
    });
  },
};

export default profileQueries;

